40|  const seedIx = argv.indexOf('--seed');
41|  const seed = seedIx === -1
42|    ? (process.env.SEED !== '' && Number.isInteger(Number(process.env.SEED)) ? Number(process.env.SEED) : DEFAULT_CITY.seed)
43|    : Number(argv[seedIx + 1]);
44|  if (!Number.isInteger(seed) || seed < 0) {
45|    console.error(`Usage: node server/main.mjs [--seed <non-negative integer>] [port]  (got "--seed ${argv[seedIx + 1]}")`);
46|    process.exit(1);
47|  }
48|  const PORT = Number(argv.filter((a, i) => i !== seedIx && (i !== seedIx + 1 || seedIx === -1))[0] ?? process.env.PORT ?? 8080);
49|  // The server owns the rules and the seed; clients regenerate the same city
50|  // from it (phase 3). Rules are pure (raceState.js) and get everything from
51|  // here injected, so tests drive them over FakeNet instead of sockets.
52|  const race = createRaceState({
53|    seed,
54|    now: () => Date.now(),
55|    send: (conn, type, data) => conn.send(encode(type, data)),
56|    close: (conn, code, reason) => conn.close(code, reason),
57|    schedule: (delayMs, fn) => setTimeout(fn, delayMs), // real timers; tests swap in FakeNet.schedule
58|  });
59|  // 0.0.0.0: reachable from other machines on the intranet, not just localhost.
